const LEVELS=[["Pre-Law Foundations","Classical foundations","🏛"],["First-Year Law School (1L)","Core legal doctrine","⚖"],["Second-Year Law School (2L)","Evidence and procedure","▤"],["Third-Year Law School (3L)","Practice and advocacy","▥"],["Bar Exam Preparation","Skills and readiness","✎"],["Advanced Legal Practice","Complex legal problems","♜"]];
function header(){return '<header class="masthead"><div class="crest">⚖</div><div class="brandtitle">LAW ACADEMY</div><div class="motto">LEARN · ANALYZE · ARGUE · ADVOCATE · LEAD</div></header>'}
function nav(selected){const tabs=[["Home","⌂","home"],["Courses","▤","courses"],["Exams","☑","exams"],["Courtroom","⚖","courtroom"],["More","☷","more"]];return '<nav class="bottom-nav" aria-label="Main navigation">'+tabs.map(([name,ico,key])=>'<button class="navitem '+(selected===key?'on':'')+'" data-nav="'+key+'"><span>'+ico+'</span><small>'+name+'</small></button>').join('')+'</nav>'}
function bindNav(){document.querySelectorAll("[data-nav]").forEach(b=>b.onclick=()=>screen(b.dataset.nav))}
function screen(name){if(name==="home")return renderHome();if(name==="courses")return renderCatalog();if(name==="exams")return renderExams();if(name==="courtroom")return renderCourtroom();return renderMore()}
function shell(contents,selected="home"){app.innerHTML='<main class="shell app-shell">'+contents+'</main>'+nav(selected);bindNav()}
function getProgress(){const total=COURSES[0].lessons.length;const done=COURSES[0].lessons.filter(x=>completed[x.id]).length;return {total,done,percent:Math.round(done/total*100)}}
function renderHome(){active=null;const p=getProgress();const next=COURSES[0].lessons.find(x=>!completed[x.id])||COURSES[0].lessons[0];const index=COURSES[0].lessons.indexOf(next);
shell('<div class="court-hero">'+header()+'<p class="hero-copy">Master the law. Build the skills<br>to think, argue, and lead.</p></div><section class="progress-panel"><div><span class="gold-label">CURRENT LEVEL</span><h2>Pre-Law Foundations</h2><p>Lesson '+(index+1)+' of '+p.total+'</p><div class="progress-row"><div class="track"><div class="fill" style="width:'+p.percent+'%"></div></div><span>'+p.percent+'%</span></div></div><div class="ring" style="--pc:'+p.percent+'%"><span>'+p.percent+'%</span><small>COURSE<br>MASTERY</small></div></section><div class="quick-grid">'+[["▤","Continue Learning","continue"],["☑","Practice Exams","exams"],["⚖","Virtual Courtroom","courtroom"],["◴","My Progress","progress"],["✎","Case Studies","cases"]].map(a=>'<button class="quick-card" data-action="'+a[2]+'"><span>'+a[0]+'</span><small>'+a[1]+'</small></button>').join('')+'</div><section class="feature-card"><span class="gold-label">FEATURED COURSE</span><h2>Introduction to the<br>American Legal System</h2><p>Discover how the courts, Constitution, and legal principles work.</p><button class="gold-button" id="resume"> '+(p.done?'Continue':'Start')+' Lesson '+(index+1)+' ›</button></section><button class="level-row case-home-link" id="caseStudiesHome"><span class="level-icon">✎</span><span class="level-text"><strong>Case Studies & Writing</strong><small>Real opinions · legal memos · guided assignments</small></span><span class="level-arrow">›</span></button><div class="section"><h3>YOUR LAW PROGRAM</h3><button class="text-link" id="allCourses">View All Courses →</button></div><div class="level-list">'+LEVELS.map((l,i)=>'<button class="level-row" data-level="'+i+'"><span class="level-icon">'+l[2]+'</span><span class="level-text"><strong>Level '+(i+1)+' · '+l[0]+'</strong><small>'+(i===0?'6 courses · 85 introductory lessons':'Curriculum in development')+'</small></span><span class="level-arrow">'+(i===0?p.percent+'%':'›')+'</span></button>').join('')+'</div><p class="footer">Independent legal education · Not an accredited law school or legal advice.</p>','home');
document.querySelector("#resume").onclick=()=>renderLesson(COURSES[0],next);document.querySelector("#allCourses").onclick=renderCatalog;document.querySelector("#caseStudiesHome").onclick=writingHome;document.querySelectorAll("[data-action]").forEach(b=>b.onclick=()=>{const a=b.dataset.action;if(a==="continue")renderLesson(COURSES[0],next);else if(a==="progress")renderProgress();else if(a==="resources")renderResources();else if(a==="cases")writingHome();else screen(a)});document.querySelectorAll("[data-level]").forEach(b=>b.onclick=()=>{if(b.dataset.level==="0")renderCatalog();else renderPlanned(LEVELS[Number(b.dataset.level)][0])})}
const FUTURE_COURSES=[["Contracts","Torts","Civil Procedure","Criminal Law","Constitutional Law","Property","Legislation & Regulation","Legal Research & Writing"],["Evidence","Criminal Procedure","Business Associations","Administrative Law","Professional Responsibility","Federal Courts","Advanced Writing"],["Trial Advocacy","Appellate Advocacy","Negotiation","Clinical Practice","Advanced Research","Specializations"],["Bar Doctrine Review","Timed Multiple Choice","Essays","Performance Tests","Full Mock Exams"],["Complex Litigation","Corporate Transactions","Constitutional Litigation","Technology & Privacy","International Law","Capstone"]];
