function renderCourse(c){app.innerHTML='<main class="shell">'+header()+'<button class="back" id="back">← All courses</button><p class="eyebrow">'+c.level+'</p><h2>'+c.title+'</h2><p class="muted">'+(c.lessons.length?'Read each lesson and pass its mastery check to mark it complete.':'This course is planned but has not yet been written. No placeholder content is counted as completed.')+'</p>'+c.lessons.map((l,i)=>'<button class="lesson" data-lesson="'+i+'"><span class="tag">Lesson '+(i+1)+(completed[l.id]?' · ✓ Mastered':'')+'</span><strong style="display:block;margin-top:8px">'+l.title+'</strong><small>'+l.time+' · lesson + question</small></button>').join('')+'<button class="button secondary" id="courseCases">Open Case Studies & Writing</button><button class="button secondary" id="home">Return to dashboard</button></main>';document.querySelector("#back").onclick=renderHome;document.querySelector("#home").onclick=renderHome;document.querySelector("#courseCases").onclick=writingHome;document.querySelectorAll("[data-lesson]").forEach(b=>b.onclick=()=>renderLesson(c,c.lessons[Number(b.dataset.lesson)]))}
