function simulationFeedback(caseFile,drafts,branches,key,branchKey){
const results=[];let words=0,selected=0;
for(let i=0;i<caseFile.stages.length;i++){
 const draft=String(drafts[key(i)]||"").trim(),n=draft?draft.split(/\s+/).length:0;words+=n;
 const branch=branches[branchKey(i)],hasBranch=branch===0||branch===1;if(hasBranch)selected++;
 const prompts=[];if(!hasBranch)prompts.push("Choose an investigation branch before drawing conclusions.");
 if(n<80)prompts.push("Develop this stage further: identify the governing rule, competing factual interpretations and missing proof.");
 if(!/because|since|therefore|however|although|whereas|but/i.test(draft))prompts.push("Explain why the evidence supports or weakens the argument instead of listing conclusions.");
 const evidence=hasBranch?SIM_BRANCHES[caseFile.id][i][2][branch]:"";
 if(hasBranch&&!/evidence|record|document|email|video|text|report|witness|fact|statement|log|permit|consent|notice|client|safety/i.test(draft))prompts.push("Tie your analysis expressly to the newly revealed evidence: "+evidence);
 if(!/however|although|on the other hand|counter|defen|alternatively|yet|whereas/i.test(draft))prompts.push("State a credible argument for the opposing side and how you would respond.");
 if(!prompts.length)prompts.push("Your writing contains several structural indicators. Check every proposition against primary authority; this tool cannot confirm whether your conclusion is correct.");
 results.push({title:caseFile.stages[i][0],words:n,feedback:prompts});
}
return {results,words,selected};
}
function renderCaseSimulation(id="park"){const caseFile=SIM_CASES.find(x=>x.id===id)||SIM_CASES[0];let drafts={};try{drafts=JSON.parse(localStorage.getItem(SIM_KEY)||"{}")||{}}catch(e){}let branches={};try{branches=JSON.parse(localStorage.getItem(SIM_BRANCH_KEY)||"{}")||{}}catch(e){}let step=0;const branchKey=n=>caseFile.id+":"+n;const key=n=>caseFile.id==="park"?String(n):caseFile.id+":"+n;const esc=x=>String(x).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");
function draw(){const q=caseFile.stages[step];shell('<div class="pagehead"><span class="gold-label">'+caseFile.topic+' · STAGE '+(step+1)+'/4</span><h1>'+caseFile.title+'</h1></div><div class="review-item"><h3>'+q[0]+'</h3><p>'+q[1]+'</p><p><strong>Assignment:</strong> '+q[2]+'</p><p>Review checkpoints: '+q[3]+'</p></div><div class="review-item"><h3>Choose your investigation</h3><p id="simBranchPrompt"></p><div id="simBranchOptions"></div><p id="simBranchOutcome" aria-live="polite"></p></div><label class="gold-label" for="simText">YOUR LEGAL REASONING</label><textarea class="writing-field" id="simText" rows="12" placeholder="Issue, rule, facts, application and counterarguments..."></textarea><div class="review-item"><h3>Professor-style challenge</h3><p id="simChallengeQuestion"></p><button class="button secondary" id="simChallenge">Reveal reasoning prompts</button><div id="simChallengeFeedback" aria-live="polite"></div></div><button class="gold-button" id="simSave">Save response</button><button class="button secondary" id="simPrevious">'+(step?'Previous stage':'All case files')+'</button><button class="button secondary" id="simNext">'+(step===3?'Review responses':'Next stage')+'</button><p id="simStatus" aria-live="polite"></p>','more');const area=document.querySelector("#simText");area.value=drafts[key(step)]||"";const branch=SIM_BRANCHES[caseFile.id][step],previous=branches[branchKey(step)];
document.querySelector("#simBranchPrompt").textContent=branch[0];
const optionBox=document.querySelector("#simBranchOptions"),outcome=document.querySelector("#simBranchOutcome");
function showBranch(selection){branches[branchKey(step)]=selection;try{localStorage.setItem(SIM_BRANCH_KEY,JSON.stringify(branches))}catch(e){}optionBox.querySelectorAll("button").forEach(b=>{b.classList.toggle("selected",Number(b.dataset.branch)===selection)});outcome.textContent=branch[2][selection];}
branch[1].forEach((label,i)=>{const b=document.createElement("button");b.className="option";b.textContent=label;b.dataset.branch=String(i);b.onclick=()=>showBranch(i);optionBox.appendChild(b)});
if(previous===0||previous===1)showBranch(previous);
const challenge=SIM_CHALLENGES[caseFile.id][step];document.querySelector("#simChallengeQuestion").textContent=challenge[0];document.querySelector("#simChallenge").onclick=()=>{document.querySelector("#simChallengeFeedback").textContent=challenge[1]+" These are hints, not a legal correctness grade.";document.querySelector("#simChallenge").disabled=true};function save(){drafts[key(step)]=area.value;try{localStorage.setItem(SIM_KEY,JSON.stringify(drafts));document.querySelector("#simStatus").textContent="Saved on this device"}catch(e){document.querySelector("#simStatus").textContent="Could not save. Copy your response before leaving."}}document.querySelector("#simSave").onclick=save;document.querySelector("#simPrevious").onclick=()=>{save();if(step){step--;draw()}else writingHome()};document.querySelector("#simNext").onclick=()=>{save();if(step<3){step++;draw()}else review()}}
function review(){shell('<div class="pagehead"><span class="gold-label">SELF-REVIEW · NOT GRADED</span><h1>'+caseFile.title+'</h1><p>Compare your responses as facts evolved. No automated legal accuracy score.</p></div>'+caseFile.stages.map((q,i)=>'<div class="review-item"><h3>'+q[0]+'</h3><p>'+esc(drafts[key(i)]||"No response")+'</p><p>Checkpoints: '+q[3]+'</p><p><strong>Evidence quality questions:</strong> '+SIM_EVIDENCE_CHECKS[caseFile.id][i].map(esc).join(' • ')+'</p><p><strong>Investigation:</strong> '+(branches[branchKey(i)]===0||branches[branchKey(i)]===1?esc(SIM_BRANCHES[caseFile.id][i][1][branches[branchKey(i)]])+" — "+esc(SIM_BRANCHES[caseFile.id][i][2][branches[branchKey(i)]]):"No branch selected")+'.</p></div>').join('')+'<div class="review-item"><h3>Simulated judicial perspectives</h3><p><strong>Argument for claimant:</strong> '+SIM_OUTCOMES[caseFile.id][0]+'</p><p><strong>Argument for respondent:</strong> '+SIM_OUTCOMES[caseFile.id][1]+'</p><p><strong>Unresolved judicial question:</strong> '+SIM_OUTCOMES[caseFile.id][2]+'</p><p>These are educational hypothetical outcomes, not a verdict, a grade, or a legal prediction.</p></div><div class="review-item"><h3>Individualized revision guide</h3><div id="simPersonalFeedback"></div><p>Automated checks consider writing length, reasoning language, and selected evidence. They cannot verify legal rules, citation validity, or argument correctness.</p></div>'+ '<button class="gold-button" id="simReturn">Edit stages</button><button class="button secondary" id="simClose">All case files</button>','more');const feedback=simulationFeedback(caseFile,drafts,branches,key,branchKey);document.querySelector("#simPersonalFeedback").innerHTML='<p>'+feedback.words+' total words · '+feedback.selected+' of 4 investigative decisions recorded</p>'+feedback.results.map(item=>'<div class="review-item"><strong>'+esc(item.title)+' — '+item.words+' words</strong><ul>'+item.feedback.map(note=>'<li>'+esc(note)+'</li>').join('')+'</ul></div>').join('');document.querySelector("#simReturn").onclick=()=>{step=0;draw()};document.querySelector("#simClose").onclick=writingHome}draw()}
