const REASONING_LABS=[{"id":"authority","title":"Authority and Research Defense","facts":"A federal legal dispute involves a persuasive out-of-circuit decision, an older opinion from the controlling circuit, and a recently amended statute.","steps":[["Identify authority","Identify the authorities that may bind the court and explain what must be verified.","Jurisdiction; hierarchy; statutory change"],["Confront adverse authority","Explain how to accurately address a controlling case that undermines your preferred argument.","Candor; distinguishing facts; subsequent history"],["Research plan","Write a source verification plan and qualified recommendation.","Primary sources; date checked; uncertainty"]]},{"id":"rights","title":"Constitutional Issue Spotting","facts":"A city denies a political permit but approves an unrelated civic celebration on a different date.","steps":[["Frame the issue","Identify legal issues and material facts required before drawing conclusions.","State action; forum; viewpoint"],["Opposing arguments","State the city's best defense and challengers' response.","Neutrality; safety; tailoring"],["Conclude carefully","Provide an objective analysis and identify missing law.","Authority; facts; uncertainty"]]},{"id":"proof","title":"Civil Litigation and Evidence","facts":"An injured visitor alleges a warehouse ignored a spill, while the business claims a warning cone existed.","steps":[["Legal elements","Identify each element of a negligence claim, distinguishing known and disputed facts.","Duty; breach; causation; damages"],["Evidence challenge","Explain how to test witnesses, documents and timeline claims.","Credibility; corroboration; records"],["Defense and conclusion","Compare the strongest arguments and identify governing state rules.","Notice; comparative fault; uncertainty"]]}];
function renderReasoningLab(id){const lab=REASONING_LABS.find(x=>x.id===id)||REASONING_LABS[0];let saved={};try{saved=JSON.parse(localStorage.getItem(REASONING_KEY)||"{}")||{}}catch(e){}let stage=0;const esc=x=>String(x).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;"),key=i=>lab.id+":"+i;
function draw(){const q=lab.steps[stage];shell('<div class="pagehead"><span class="gold-label">REASONING LAB '+(stage+1)+'/3</span><h1>'+lab.title+'</h1><p>'+lab.facts+'</p></div><div class="review-item"><h3>'+q[0]+'</h3><p>'+q[1]+'</p></div><textarea class="writing-field" id="reasonText" rows="10" aria-label="Your written legal analysis"></textarea><button id="reasonHint" class="button secondary">Review criteria</button><p id="reasonCriteria" aria-live="polite"></p><button id="reasonSave" class="gold-button">Save writing</button><button id="reasonBack" class="button secondary">Back</button><button id="reasonNext" class="button secondary">'+(stage===2?'Review responses':'Next challenge')+'</button><p id="reasonStatus" aria-live="polite"></p>','more');const input=document.querySelector("#reasonText");input.value=saved[key(stage)]||"";function save(){saved[key(stage)]=input.value;try{localStorage.setItem(REASONING_KEY,JSON.stringify(saved));document.querySelector("#reasonStatus").textContent="Saved locally"}catch(e){document.querySelector("#reasonStatus").textContent="Save failed; please copy your response."}}document.querySelector("#reasonSave").onclick=save;document.querySelector("#reasonHint").onclick=()=>document.querySelector("#reasonCriteria").textContent=q[2]+" — these are review prompts, not grading.";document.querySelector("#reasonBack").onclick=()=>{save();if(stage){stage--;draw()}else writingHome()};document.querySelector("#reasonNext").onclick=()=>{save();if(stage<2){stage++;draw()}else review()}}
function review(){shell('<div class="pagehead"><span class="gold-label">SELF-REVIEW, NOT GRADED</span><h1>'+lab.title+'</h1></div>'+lab.steps.map((q,i)=>'<div class="review-item"><h3>'+esc(q[0])+'</h3><p>'+esc(saved[key(i)]||"No response")+'</p><p>Review: '+esc(q[2])+'</p></div>').join('')+'<button id="reasonEdit" class="gold-button">Edit responses</button><button id="reasonExit" class="button secondary">Case Studies</button>','more');document.querySelector("#reasonEdit").onclick=()=>{stage=0;draw()};document.querySelector("#reasonExit").onclick=writingHome}draw()}
const RESEARCH_CAPSTONE_KEY="law-academy-research-capstone-v1";
const RESEARCH_CAPSTONE=[
["Identify the legal questions","Hypothetical: A city rejects a park demonstration permit, asserting traffic concerns. A similar pro-city gathering received approval. A message mentions officials' dislike of critics.","Write a neutral question presented. Identify the government actor, forum, possibly relevant rights and missing facts.","Issue framing; source of authority; material facts"],
["Build a source log","Research the First Amendment's text and applicable cases using the Constitution Annotated and Supreme Court opinions. Record URLs and access dates.","List at least two primary authorities, the court or issuer, year, relevant proposition, and what still needs verification.","Primary versus secondary law; citations; currency"],
["Organize the evidence","Consider the permit decisions, conflicting event dates, road-closure report and internal message. All facts here are hypothetical.","Separate confirmed scenario facts, disputed inferences, missing documents and potential credibility problems.","Evidence; comparison; missing facts"],
["Argue both sides","The challengers allege viewpoint discrimination. The city claims neutral traffic restrictions and available alternatives.","Write arguments for both parties and distinguish a rule's text from how it was enforced.","Opposing arguments; tailoring; uncertainty"],
["Draft the final memorandum","Synthesize your research and evidence; do not assume the case's outcome.","Prepare a structured objective memorandum with Question Presented, Brief Answer, Facts, Discussion, and Conclusion. Identify controlling-law gaps.","IRAC/CREAC; citations; counterarguments"],
["Audit and revise","Review your draft for unsupported propositions, potentially stale authorities and the strongest adverse evidence.","Write an improvement plan that identifies at least three needed source checks or substantive revisions.","Verification; factual accuracy; limitations"]
];
function renderResearchCapstone(){let store={};try{store=JSON.parse(localStorage.getItem(RESEARCH_CAPSTONE_KEY)||"{}")||{}}catch(e){}let stage=0;const esc=x=>String(x).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");function save(input){store[String(stage)]=input.value;try{localStorage.setItem(RESEARCH_CAPSTONE_KEY,JSON.stringify(store));return true}catch(e){return false}}
function draw(){const task=RESEARCH_CAPSTONE[stage];shell('<div class="pagehead"><span class="gold-label">LEVEL 1 · RESEARCH CAPSTONE '+(stage+1)+' / 6</span><h1>'+task[0]+'</h1><p>'+task[1]+'</p></div><div class="review-item"><h3>Your assignment</h3><p>'+task[2]+'</p><p><strong>Review standard:</strong> '+task[3]+'</p></div><a class="level-row" href="https://constitution.congress.gov/browse/amendment-1/" target="_blank" rel="noopener"><span class="level-icon">▤</span><span class="level-text"><strong>Constitution Annotated</strong><small>Primary text and congressional analysis</small></span><span class="level-arrow">↗</span></a><label class="gold-label" for="capstoneWriting">YOUR RESEARCH AND ANALYSIS</label><textarea id="capstoneWriting" class="writing-field" rows="12"></textarea><button class="gold-button" id="capstoneSave">Save response</button><button class="button secondary" id="capstonePrevious">'+(stage?"Previous stage":"Case Studies")+'</button><button class="button secondary" id="capstoneNext">'+(stage===5?"Review portfolio":"Next stage")+'</button><p id="capstoneStatus" aria-live="polite"></p>','more');const input=document.querySelector("#capstoneWriting");input.value=store[String(stage)]||"";document.querySelector("#capstoneSave").onclick=()=>document.querySelector("#capstoneStatus").textContent=save(input)?"Saved on this device":"Save failed; copy your response";document.querySelector("#capstonePrevious").onclick=()=>{save(input);if(stage){stage--;draw()}else writingHome()};document.querySelector("#capstoneNext").onclick=()=>{save(input);if(stage<5){stage++;draw()}else review()}}
function review(){let filled=0,words=0;const content=RESEARCH_CAPSTONE.map((q,i)=>{const draft=String(store[String(i)]||"").trim();if(draft)filled++;words+=draft?draft.split(/\s+/).length:0;return '<div class="review-item"><h3>'+esc(q[0])+'</h3><p>'+esc(draft||"No response")+'</p><p><strong>Review criteria:</strong> '+esc(q[3])+'</p></div>'}).join('');shell('<div class="pagehead"><span class="gold-label">CAPSTONE SELF-REVIEW · NOT GRADED</span><h1>Research Portfolio</h1><p>'+filled+' of 6 stages drafted · '+words+' total words. This is progress only, not evidence of legal accuracy.</p></div>'+content+'<div class="review-item"><h3>Before external review</h3><p>Verify each authority and its subsequent history, separate allegations from facts, address both sides, and confirm the governing law. Graduation remains locked pending qualified independent evaluation.</p></div><button class="gold-button" id="capstoneEdit">Edit portfolio</button><button class="button secondary" id="capstoneExit">Case Studies</button>','more');document.querySelector("#capstoneEdit").onclick=()=>{stage=0;draw()};document.querySelector("#capstoneExit").onclick=writingHome}draw()}
function writingHome(){shell('<div class="pagehead"><span class="gold-label">PRE-LAW · WRITING LAB</span><h1>Case Studies & Writing</h1><p>Practice legal analysis and save drafts on this device. Exercises are ungraded.</p></div><div class="section"><h3>LEVEL 1 RESEARCH CAPSTONE</h3></div><button class="level-row" id="researchCapstoneLaunch"><span class="level-icon">★</span><span class="level-text"><strong>Six-stage Research & Writing Capstone</strong><small>Primary authorities · evidence · arguments · revision</small></span><span class="level-arrow">›</span></button><div class="section"><h3>STRUCTURED REASONING LABS</h3></div><div class="level-list">'+REASONING_LABS.map(l=>'<button class="level-row" data-reason="'+l.id+'"><span class="level-icon">▤</span><span class="level-text"><strong>'+l.title+'</strong><small>Three written challenges</small></span><span class="level-arrow">›</span></button>').join('')+'</div><div class="section"><h3>INTERACTIVE CASE FILES</h3></div><div class="level-list">'+SIM_CASES.map(c=>'<button class="level-row" data-sim="'+c.id+'"><span class="level-icon">⚖</span><span class="level-text"><strong>'+c.title+'</strong><small>'+c.topic+' · 4 stages · saved writing</small></span><span class="level-arrow">›</span></button>').join('')+'</div><div class="level-list">'+WRITING_TASKS.map(t=>'<button class="level-row" data-write="'+t.id+'"><span class="level-icon">✎</span><span class="level-text"><strong>'+t.title+'</strong><small>'+t.course+' · '+(writingDrafts[t.id]?'Draft saved':'Not started')+'</small></span><span class="level-arrow">›</span></button>').join('')+'</div>','more');document.querySelector("#researchCapstoneLaunch").onclick=renderResearchCapstone;document.querySelectorAll("[data-reason]").forEach(b=>b.onclick=()=>renderReasoningLab(b.dataset.reason));document.querySelectorAll("[data-sim]").forEach(x=>x.onclick=()=>renderCaseSimulation(x.dataset.sim));document.querySelectorAll("[data-write]").forEach(x=>x.onclick=()=>writingTask(WRITING_TASKS.find(t=>t.id===x.dataset.write)))}
function analyzeDraft(t,value){
const str=value.trim(),words=str?str.split(/\s+/).length:0;
const concepts=t.id==="marbury"?[
["Facts and posture",/marbury|commission|appointment|mandamus|delivery/i,"Identify the commission dispute, who sought relief, and how the case reached the Supreme Court."],
["Jurisdiction",/jurisdiction|article\s*(iii|3)|original/i,"Explain why the Court's original jurisdiction was central to the outcome."],
["Judicial review",/judicial\s*review|unconstitutional|constitution|invalid/i,"Address the conflict between the statute and the Constitution, using the actual opinion."],
["Holding and reasoning",/holding|held|reason|court\s*(denied|concluded|found)/i,"Separate the Court's disposition from its wider reasoning."]
]:[
["Issue and rule",/issue|rule|negligen|duty/i,"Frame a precise negligence issue and identify the governing elements."],
["Breach",/breach|spill|notice|warning|clean/i,"Apply the employee's notice and 20-minute delay to the standard of care."],
["Causation and harm",/caus|injur|damage|harm/i,"Analyze factual causation, legal causation, and the documented injury separately."],
["Counterarguments",/however|although|counter|defen|comparative|unknown|jurisdiction/i,"Address a plausible defense and identify the missing jurisdiction-specific law."]
];
const missing=concepts.filter(x=>!x[1].test(str));
const items=[];
if(words<120)items.push("Your draft is short for this exercise ("+words+" words). Develop the rule and its application with specific evidence.");
if(!/because|therefore|since|given|however|although|while/i.test(str))items.push("Explain why the facts support your conclusion; connect claims with reasoning, not only labels.");
for(const m of missing)items.push(m[2]);
if(!items.length)items.push("Your draft mentions the major checkpoints. Verify each proposition against the source; keyword checks cannot establish legal accuracy.");
return {words,covered:concepts.length-missing.length,total:concepts.length,items};
}
function writingTask(t){shell('<div class="pagehead"><span class="gold-label">'+t.course+' · WRITING ASSIGNMENT</span><h1>'+t.title+'</h1><p>'+t.background+'</p></div><a class="level-row" href="'+t.source+'" target="_blank" rel="noopener"><span class="level-icon">▤</span><span class="level-text"><strong>Read the source</strong><small>External legal reference</small></span><span class="level-arrow">↗</span></a><div class="review-item"><h3>Your assignment</h3><p>'+t.prompt+'</p></div><label class="gold-label" for="writingDraft">YOUR DRAFT</label><textarea id="writingDraft" class="writing-field" rows="13" placeholder="Write your analysis here..."></textarea><button id="saveDraft" class="gold-button">Save draft</button><button id="reviewDraft" class="button secondary" type="button">Get guided feedback</button><div id="guidedFeedback" aria-live="polite"></div><span id="draftStatus" class="muted" aria-live="polite"></span>'+rubricWidget(t)+'<div class="review-item"><h3>Self-review checklist</h3>'+t.checks.map(c=>'<label class="check-line"><input type="checkbox"> '+c+'</label>').join('')+'<p>Checklist completion does not constitute an assessed grade.</p></div><div class="review-item"><h3>Review handoff</h3><p>Copy your assignment and draft for an outside reviewer. No submission or grading happens automatically.</p><button id="copyReview" class="button secondary" type="button">Copy review packet</button><p id="copyStatus" aria-live="polite"></p></div><button id="writingBack" class="button secondary">Back to assignments</button>','more');const field=document.querySelector("#writingDraft");field.value=writingDrafts[t.id]||"";document.querySelectorAll("[data-rubric]").forEach(el=>{el.value=String((rubricReviews[t.id]||[])[Number(el.dataset.rubric)]||"")});document.querySelector("#saveRubric").onclick=()=>{const vals=Array.from(document.querySelectorAll("[data-rubric]")).map(el=>Number(el.value)||0);rubricReviews[t.id]=vals;localStorage.setItem(RUBRIC_KEY,JSON.stringify(rubricReviews));const n=vals.filter(Boolean).length;document.querySelector("#rubricStatus").textContent=n===RUBRIC.length?"Saved: "+vals.reduce((a,b)=>a+b,0)+" / 20 self-assessed points (not a grade)":"Saved "+n+" / 5 criterion ratings (not a grade)"};const save=()=>{writingDrafts[t.id]=field.value;localStorage.setItem(WRITING_KEY,JSON.stringify(writingDrafts));document.querySelector("#draftStatus").textContent="Saved on this device"};document.querySelector("#saveDraft").onclick=save;document.querySelector("#copyReview").onclick=async()=>{save();const packet=t.title+"\\nAssignment: "+t.prompt+"\\nDraft:\\n"+field.value;try{await navigator.clipboard.writeText(packet);document.querySelector("#copyStatus").textContent="Review packet copied"}catch(e){document.querySelector("#copyStatus").textContent="Clipboard unavailable; manually copy your draft"}};document.querySelector("#reviewDraft").onclick=()=>{save();const a=analyzeDraft(t,field.value);const escapeText=x=>x.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");document.querySelector("#guidedFeedback").innerHTML='<div class="review-item"><span class="gold-label">STRUCTURED WRITING FEEDBACK · NOT A GRADE</span><h3>Revision guidance</h3><p>'+a.words+' words · '+a.covered+' of '+a.total+' topic indicators detected</p><ul class="feedback-points">'+a.items.map(x=>"<li>"+escapeText(x)+"</li>").join("")+'</ul><p>These checks look for terms and structure, not whether your legal arguments are true. Verify the primary source, compare both sides, and revise your draft.</p></div>';document.querySelector("#guidedFeedback").scrollIntoView({behavior:"smooth",block:"nearest"})};document.querySelector("#writingBack").onclick=()=>{save();writingHome()}}
renderHome();
